// @ts-check
// Post-processing step for `generate:api` (CONTRACT A3).
//
// @hey-api/openapi-ts stamps each file with `// This file is auto-generated by
// @hey-api/openapi-ts` but not the machine-recognized `// @generated` marker
// the in-sync guard test (`generated-banner.test.ts`) asserts. This prepends a
// deterministic `// @generated` line to every emitted .ts file under
// src/api/generated/ (idempotent: only when absent), so the output stays
// byte-stable across runs and carries the banner.
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const generatedRoot = resolve(here, "..", "src/api/generated");

const MARKER = "// @generated";

/** @param {string} dir */
function walk(dir) {
  for (const entry of readdirSync(dir).sort()) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      walk(full);
    } else if (entry.endsWith(".ts")) {
      stamp(full);
    }
  }
}

/** @param {string} file */
function stamp(file) {
  const text = readFileSync(file, "utf8");
  if (text.startsWith(`${MARKER}\n`)) return;
  writeFileSync(file, `${MARKER}\n${text}`);
}

walk(generatedRoot);
